var i=`0136-chakapuli`;var t=`world-0136`;var a=`GE`;var s=`western-asia`;var r=4;var o=85;var l={en:`Chakapuli`,ua:`Чакапулі`};var g={en:`A classic dish from Georgia, featuring lamb shoulder, green onion, tarragon, cilantro. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Грузія. Основні складники: лопатка ягняти, зелена цибуля, естрагон, кінза. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var d=[{en:`Pat the main ingredients dry. Brown in a hot heavy pan in batches for about 12 minutes, turning to color all sides.`,ua:`Обсушіть основні продукти. Обсмажуйте їх порціями на добре розігрітій важкій сковороді приблизно 12 хвилин, перевертаючи для рівної скоринки.`,t:[`searing`],m:12,i:[[`lamb-shoulder`,650,`g`],[`sunflower-oil`,35,`ml`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 10 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 10 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:10,i:[[`green-onion`,180,`g`],[`tarragon`,65,`g`],[`cilantro`,35,`g`]]},{en:`Add the braising liquid and seasonings, cover and cook gently for about 60 minutes until the meat is tender and safely cooked.`,ua:`Додайте рідину та приправи для тушкування, накрийте кришкою й готуйте на малому вогні приблизно 60 хвилин до м’якості та повної готовності м’яса.`,t:[`braising`],m:60,i:[[`dry-white-wine`,230,`ml`],[`tkemali-sauce`,150,`g`],[`water`,270,`ml`],[`table-salt`,null,`to_taste`],[`ground-black-pepper`,null,`to_taste`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`parsley`,20,`g`]]}];var u={slug:i,id:t,country:`GE`,region:s,servings:4,minutes:85,title:l,text:g,steps:d};export{a as country,u as default,t as id,o as minutes,s as region,r as servings,i as slug,d as steps,g as text,l as title};